source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter, deque
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = [(r,c)]
            seen.add((r,c))
            cells = []
            while q:
                y,x = q.pop()
                cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            # Hollow rectangular objects have an empty rectangular center; color the hole.
            if maxr-minr >= 2 and maxc-minc >= 2:
                border = {(y,x) for y,x in cells if y in (minr,maxr) or x in (minc,maxc)}
                if border.issubset(set(cells)):
                    fill = 2 if color == 9 and bg == 8 else 7
                    for y in range(minr+1,maxr):
                        for x in range(minc+1,maxc):
                            if g[y][x] == bg:
                                g[y][x] = fill
    return g
